const crypto = require('crypto');

function pubKeyFromHex(hex) {
  const raw = Buffer.from(hex, 'hex');
  const der = Buffer.concat([Buffer.from('302a300506032b6570032100', 'hex'), raw]);
  return crypto.createPublicKey({ key: der, format: 'der', type: 'spki' });
}

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-signature-ed25519'];
const timestamp = headers['x-signature-timestamp'];
const rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');

let valid = false;
try {
  const publicKey = pubKeyFromHex($env.DISCORD_PUBLIC_KEY);
  const message = Buffer.from(timestamp + rawBody, 'utf8');
  const sigBuf = Buffer.from(signature, 'hex');
  valid = crypto.verify(null, message, publicKey, sigBuf);
} catch (e) {
  valid = false;
}

let interaction = null;
try {
  interaction = JSON.parse(rawBody);
} catch (e) {
  interaction = null;
}

return [{ json: { valid, interaction } }];

function parseStartDate(str) {
  if (!str) return new Date().toISOString();
  const m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})$/);
  if (!m) return new Date().toISOString();
  const day = Number(m[1]), month = Number(m[2]), year = Number(m[3]), hour = Number(m[4]), minute = Number(m[5]);
  if (month < 1 || month > 12 || day < 1 || day > 31 || hour > 23 || minute > 59) return new Date().toISOString();
  const pad = (n) => String(n).padStart(2, '0');
  return `${year}-${pad(month)}-${pad(day)}T${pad(hour)}:${pad(minute)}:00+07:00`;
}

const interaction = $('Verify Signature').first().json.interaction;
const data = interaction.data || {};
const name = data.name || '';
const action = name === 'ferment_start' ? 'start' : (name === 'ferment_stop' ? 'stop' : (name === 'ferment_status' ? 'status' : 'unknown'));

const params = {};
(data.options || []).forEach(opt => { params[opt.name] = opt.value; });

return [{
  json: {
    action,
    pill: params.pill,
    controller: params.controller,
    beer: params.beer,
    start_date: parseStartDate(params.date),
    application_id: interaction.application_id,
    interaction_token: interaction.token
  }
}];

