const cmd = $('Parse Interaction Command').first().json;
return [{
  json: {
    content: '⚠️ ไม่พบ batch ที่ active อยู่สำหรับ Pill: ' + cmd.pill,
    application_id: cmd.application_id,
    interaction_token: cmd.interaction_token
  }
}];

const batch = $input.first().json;

const startDate = new Date(batch.start_date);
const hoursSinceStart = (Date.now() - startDate.getTime()) / 3600000;

const pillSeries = Array.isArray(batch.pill_series) ? batch.pill_series : [];
const controllerSeries = Array.isArray(batch.controller_series) ? batch.controller_series : [];

const latestPill = pillSeries.length ? pillSeries[pillSeries.length - 1] : null;
const latestController = controllerSeries.length ? controllerSeries[controllerSeries.length - 1] : null;

// อุณหภูมิหมักจริงของ batch นี้ (เฉลี่ยจาก Pill ช่วง 72 ชม.แรก) ใช้เป็น
// baseline เทียบแบบสัมพัทธ์ แทนเลของศาตายตัว เพราะแต่ละ batch/ยีสต์หมัก
// ที่อุณหภูมิไม่เท่ากัน
const fermentationTempPoints = pillSeries.filter(p => {
  const hoursSincePoint = (new Date(p.t) - startDate) / 3600000;
  return hoursSincePoint >= 0 && hoursSincePoint <= 72 && p.temp != null;
});
const fermentationBaselineTemp = fermentationTempPoints.length
  ? Number((fermentationTempPoints.reduce((sum, p) => sum + p.temp, 0) / fermentationTempPoints.length).toFixed(2))
  : null;

let loggedVelocity = null;
if (pillSeries.length >= 2) {
  const first = pillSeries[0], last = pillSeries[pillSeries.length - 1];
  const hoursSpan = (new Date(last.t) - new Date(first.t)) / 3600000;
  if (hoursSpan > 0 && first.sg != null && last.sg != null) {
    loggedVelocity = (last.sg - first.sg) / (hoursSpan / 24);
  }
}

const pillSeriesText = pillSeries.length
  ? pillSeries.map(p => `${p.t} | SG=${p.sg != null ? p.sg.toFixed(4) : '-'} | temp=${p.temp ?? '-'}°C`).join('\n')
  : '(ไม่มีข้อมูล)';
const controllerSeriesText = controllerSeries.length
  ? controllerSeries.map(p => `${p.t} | temp=${p.temp ?? '-'}°C | target=${p.target ?? '-'}°C`).join('\n')
  : '(ไม่มีข้อมูล)';

const promptText = `คุณคือผู้เชี่ยวชาญการหมักเบียร์ (อ้างอิงหลักการจาก BJCP Yeast & Fermentation guide, John Palmer "How to Brew", Brew Your Own Fermentation Timeline) วิเคราะห์ว่า batch นี้อยู่เฟสไหนใน 6 เฟสนี้ โดยดูจาก "กราฟ" gravity/อุณหภูมิทั้งเส้นที่ให้ด้านล่าง (เรียงตามเวลา จากเก่าไปใหม่) ไม่ใช่แค่จุดเดียว:

1. lag (0-24 ชม.แรกหลัง pitch): ยีสต์ปรับตัว ยังไม่มี krausen ชัดเจน กราฟ gravity แทบไม่ขยับจากค่าเริ่มต้น แทบไม่มีผลต่างอุณหภูมิระหว่าง pill กับตู้ควบคุม

2. active_ferment (วันที่ 1-4, หนักสุดมักอยู่ใน 48-72 ชม.แรก): high krausen, กราฟ gravity ลาดชันลงเร็วที่สุดของทั้งเส้น, pill มักอุ่นกว่าตู้ควบคุมชัดเจน (2-5°C, ปฏิกิริยาคายความร้อน)

3. slowing: กราฟ gravity เริ่มโค้งผ่อนความชันลงจากช่วงชันสุด แต่ยังลดต่อเนื่องชัดเจน (ไม่แบนราบ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมเริ่มแคบลง

4. fg_stable: กราฟ gravity แบนราบต่อเนื่องอย่างน้อย 24-48 ชม. (ไม่ลดต่อแล้วอย่างมีนัยสำคัญ) ผลต่างอุณหภูมิ pill-ตู้ควบคุมใกล้ 0
   ⚠️ ถ้ากราฟแบนเร็วผิดปกติ (เช่นภายใน 2-3 วันแรก) หรือแบนที่ค่าซึ่งยังสูงมากเทียบกับช่วงต้นกราฟ อาจเป็น "stuck fermentation" ให้ระบุความสงสัยไว้ใน reasoning ด้วย (ไม่ต้องเปลี่ยน phase ที่ตอบ แค่เตือนไว้)

5. diacetyl_rest: ต้องผ่าน fg_stable มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง ไม่ใช่อุณหภูมิตู้ควบคุม) ถูกยกขึ้นจาก "อุณหภูมิหมักปกติของ batch นี้" (ดูค่าที่ให้ไว้ด้านล่าง) ประมาณ +2 ถึง +4°C ค้างไว้ 2-3 วัน (จำเป็นสำหรับ lager, แนะนำสำหรับ ale ส่วนใหญ่แม้ไม่บังคับ) — **นี่คือช่วงสัมพัทธ์ ไม่ใช่ตัวเลของศาตายตัว** เพราะแต่ละ batch/ยีสต์หมักที่อุณหภูมิต่างกัน (เช่น batch ที่หมักปกติ 18°C แล้วยกไป 20-22°C ก็นับเป็น diacetyl_rest ได้ ไม่จำเป็นต้องอยู่ในช่วง 16-18°C แบบตายตัว) ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเสมอ ส่วน target/อุณหภูมิตู้ควบคุมเป็นแค่ข้อมูลเสริมว่าตู้กำลังพยายามไล่ตามคำสั่งอยู่หรือยัง (ห้ามใช้แค่ target/ตู้ยังไม่ถึงมาสรุปว่ายังไม่เข้า diacetyl_rest ทั้งที่ Pill เองถึงแล้ว)

6. cold_crash: ต้องผ่าน fg_stable (และปกติ diacetyl_rest) มาก่อน แล้ว "อุณหภูมิ Pill" (เบียร์จริง) ลดลงเหลือ 0-4°C ค้างไว้ 1-3 วัน (ale ~1-2 วัน, lager ~2-3 วัน) — ใช้อุณหภูมิ Pill ตัดสินเป็นหลักเช่นเดียวกับข้อ 5

ข้อมูล batch "${batch.beer_name || '(ไม่ระบุชื่อ)'}":
- เริ่มหมักมาแล้ว: ${hoursSinceStart.toFixed(1)} ชั่วโมง (${(hoursSinceStart / 24).toFixed(1)} วัน)
- เฟสล่าสุดที่บันทึกไว้: ${batch.current_phase}
- อุณหภูมิ Pill (เบียร์จริง) ล่าสุด: ${latestPill && latestPill.temp != null ? latestPill.temp : 'ไม่มีข้อมูล'}°C ← ใช้ตัวนี้ตัดสิน diacetyl_rest/cold_crash เป็นหลัก
- อุณหภูมิหมักปกติของ batch นี้ (เฉลี่ย Pill ช่วง 72 ชม.แรก): ${fermentationBaselineTemp ?? 'ไม่มีข้อมูล'}°C ← baseline สำหรับเทียบว่ายกขึ้น +2 ถึง +4°C แล้วหรือยัง (diacetyl_rest)
- อุณหภูมิตู้ควบคุมล่าสุด: ${latestController && latestController.temp != null ? latestController.temp : 'ไม่มีข้อมูล'}°C (ข้อมูลเสริมเท่านั้น)
- target temperature ที่ตู้ควบคุมตั้งไว้ปัจจุบัน: ${latestController && latestController.target != null ? latestController.target : 'ไม่มีข้อมูล'}°C

กราฟ gravity/อุณหภูมิ Pill ตามเวลา (${pillSeries.length} จุด, เรียงเก่า→ใหม่):
${pillSeriesText}

กราฟอุณหภูมิตู้ควบคุมตามเวลา (${controllerSeries.length} จุด, เรียงเก่า→ใหม่):
${controllerSeriesText}

ตอบกลับเป็น JSON เท่านั้น ห้ามมีข้อความอื่นปนก่อน/หลัง รูปแบบ:
{"phase": "<lag|active_ferment|slowing|fg_stable|diacetyl_rest|cold_crash>", "reasoning": ["<เหตุผลข้อที่ 1 สั้นๆ ภาษาไทย อ้างอิงข้อมูลที่ให้มาประกอบ>", "<เหตุผลข้อที่ 2>", "..."]}
reasoning ต้องเป็น array ของ string สั้นๆ ไม่เกิน 4 ข้อ แต่ละข้อคือประเด็นเดียว ไม่ใช่ paragraph ยาวๆ`;

const ogSg = pillSeries.length ? pillSeries[0].sg : null;
const currentSg = latestPill ? latestPill.sg : null;
const abvPercent = (ogSg != null && currentSg != null)
  ? Number(((ogSg - currentSg) * 131.25).toFixed(2))
  : null;

return [{
  json: {
    batch_id: batch.batch_id,
    beer_name: batch.beer_name,
    current_phase: batch.current_phase,
    prep_alerted_for_phase: batch.prep_alerted_for_phase,
    gravity_sg: latestPill ? latestPill.sg : null,
    temperature_c: latestPill ? latestPill.temp : null,
    pill_time_utc: latestPill ? latestPill.t : null,
    gravity_velocity: loggedVelocity,
    controller_temp_c: latestController ? latestController.temp : null,
    target_temperature_c: latestController ? latestController.target : null,
    controller_time_utc: latestController ? latestController.t : null,
    abv_percent: abvPercent,
    prompt: promptText
  }
}];

// comma ในข้อความ reasoning ทำให้ Postgres queryReplacement (comma-separated
// string แบบเก่า) เลื่อนตำแหน่ง parameter ผิด แทนที่ comma ด้วยรูปเต็มความกว้าง (，)
function sanitizeForQueryReplacement(text) {
  return typeof text === 'string' ? text.replace(/,/g, '，') : text;
}

const src = $('Build Status Analysis Prompt').first().json;
const claudeResponse = $input.first().json;
let phase = null, reasoning = null;
try {
  const textBlock = (claudeResponse.content || []).find(c => c.type === 'text');
  let text = textBlock ? textBlock.text : undefined;
  if (text) {
    text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  }
  const parsed = JSON.parse(text);
  phase = parsed.phase;
  reasoning = sanitizeForQueryReplacement(Array.isArray(parsed.reasoning)
    ? parsed.reasoning.map(line => '• ' + line).join('\n')
    : String(parsed.reasoning));
} catch (e) {
  const textBlock = (claudeResponse.content || []).find(c => c.type === 'text');
  const rawText = textBlock ? textBlock.text : '';
  const phaseMatch = rawText.match(/"phase"\s*:\s*"([a-z_]+)"/);
  if (phaseMatch) {
    phase = phaseMatch[1];
    reasoning = sanitizeForQueryReplacement('⚠️ กู้ phase จาก JSON ที่ไม่สมบูรณ์ (regex fallback, ' + String(e) + ')');
  } else {
    phase = src.current_phase;
    reasoning = sanitizeForQueryReplacement('AI response parse error: ' + String(e));
  }
}

return [{
  json: {
    batch_id: src.batch_id,
    beer_name: src.beer_name,
    previous_phase: src.current_phase,
    detected_phase: phase,
    phase_changed: phase !== src.current_phase,
    reasoning,
    gravity_sg: src.gravity_sg,
    temperature_c: src.temperature_c,
    pill_time_utc: src.pill_time_utc,
    gravity_velocity: src.gravity_velocity,
    controller_temp_c: src.controller_temp_c,
    target_temperature_c: src.target_temperature_c,
    controller_time_utc: src.controller_time_utc,
    abv_percent: src.abv_percent
  }
}];

const cmd = $('Parse Interaction Command').first().json;
const r = $('Parse Status Analysis').first().json;

const pillTimeText = r.pill_time_utc
  ? DateTime.fromISO(r.pill_time_utc).setZone('Asia/Bangkok').toFormat('d/M/yyyy HH:mm')
  : 'ไม่มีข้อมูล';
const controllerTimeText = r.controller_time_utc
  ? DateTime.fromISO(r.controller_time_utc).setZone('Asia/Bangkok').toFormat('d/M/yyyy HH:mm')
  : 'ไม่มีข้อมูล';

const content = '📊 สถานะการหมัก: ' + (r.beer_name || '(ไม่ระบุชื่อ)') + ' (Pill: ' + cmd.pill + ')\n'
  + 'gravity ล่าสุด: ' + (r.gravity_sg ?? 'ไม่มีข้อมูล') + ' SG (ณ ' + pillTimeText + ')\n'
  + 'อุณหภูมิ Pill: ' + (r.temperature_c ?? 'ไม่มีข้อมูล') + '°C\n'
  + 'อุณหภูมิตู้ควบคุม: ' + (r.controller_temp_c ?? 'ไม่มีข้อมูล') + '°C (target ' + (r.target_temperature_c ?? 'ไม่มีข้อมูล') + '°C, ณ ' + controllerTimeText + ')\n'
  + 'ABV โดยประมาณ: ' + (r.abv_percent ?? 'ไม่มีข้อมูล') + '%\n\n'
  + 'เฟส (วิเคราะห์สดตอนนี้): ' + r.detected_phase + (r.phase_changed ? ' (เปลี่ยนจาก ' + r.previous_phase + ')' : '') + '\n\n'
  + r.reasoning;

return [{
  json: {
    content,
    application_id: cmd.application_id,
    interaction_token: cmd.interaction_token
  }
}];
